def calculate_sequence(N):
    # Initialize a list to store a_n, using 1-based indexing concept, so list size N+1
    a = [0] * (N + 1)
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Check if indices are valid before accessing them. 
        # Since a_k are positive integers for k>=1, a_{n-1} >= 1.
        # Also, a_{n-1} is generally expected to be smaller than n, 
        # and a_{n - a_{n-1}} should be positive.

        an_minus_1 = a[n-1]

        # First term: a_{a_{n-1}}
        if an_minus_1 <= N:
            term1 = a[an_minus_1]
        else:
            # This should not happen for small N if the sequence is growing slowly
            # If it does, we cannot calculate it with this N.
            term1 = float('inf') 

        # Second term: a_{n - a_{n-1}}
        index2 = n - an_minus_1
        if index2 >= 1 and index2 <= N:
            term2 = a[index2]
        else:
            term2 = float('inf') # Index out of bounds or non-positive

        if term1 != float('inf') and term2 != float('inf'):
            a[n] = term1 + term2
        else:
            a[n] = -1 # Indicate failure to compute

    return a[1:N+1]

N = 20
