is_monotonic = all(sequence[i] >= sequence[i-1] for i in range(1, len(sequence)))
print(f"\nSequence is non-decreasing: {is_monotonic}")

def a(n):
    if n == 1 or n == 2:
        return 1

    # We will calculate up to n=16 to check the power-of-two pattern

    memo = {1: 1, 2: 1}

    for i in range(3, 17):
        if i not in memo:
            # Need a_i = a_{a_{i-1}} + a_{i - a_{i-1}}
            a_prev = memo[i-1]

            # Check if needed terms exist
            if a_prev not in memo or (i - a_prev) not in memo:
                 # This should only happen if the sequence explodes faster than we expected
                 # but for small i, this won't happen.
                 pass 

            term1 = memo[a_prev]
            term2 = memo[i - a_prev]

            memo[i] = term1 + term2

    return memo

sequence = a()
print("Sequence up to 16:", sequence)
